        field_combo.hwpe_job_dep.lengths.b_num_words.load_next = load_next_c;
    end
    always_ff @(posedge clk or negedge arst_n) begin
        if(~arst_n) begin
            field_storage.hwpe_job_dep.lengths.b_num_words.value <= 16'h0;
        end else begin
            if(field_combo.hwpe_job_dep.lengths.b_num_words.load_next) begin
                field_storage.hwpe_job_dep.lengths.b_num_words.value <= field_combo.hwpe_job_dep.lengths.b_num_words.next;
            end
        end
    end
    assign hwif_out.hwpe_job_dep.lengths.b_num_words.value = field_storage.hwpe_job_dep.lengths.b_num_words.value;
    assign hwif_out.hwpe_job_indep.reserved.reserved.value = 32'h0;

    //--------------------------------------------------------------------------
    // Write response
    //--------------------------------------------------------------------------
    assign cpuif_wr_ack = decoded_req & decoded_req_is_wr;
    // Writes are always granted with no error response
    assign cpuif_wr_err = '0;

    //--------------------------------------------------------------------------
    // Readback
    //--------------------------------------------------------------------------

    logic [31:0] rd_mux_addr;
    assign rd_mux_addr = decoded_addr;

    logic readback_err;
    logic readback_done;
    logic [31:0] readback_data;
    always_comb begin
        automatic logic [31:0] readback_data_var;
        readback_data_var = '0;
        if(rd_mux_addr == 32'h0) begin
            readback_data_var[31:2] = 30'h0;
        end
        if(rd_mux_addr == 32'h4) begin
            readback_data_var[31:0] = hwif_in.hwpe_ctrl.acquire.acquire.next;
        end
        if(rd_mux_addr == 32'h8) begin
            readback_data_var[0] = field_storage.hwpe_ctrl.autotrigger.autotrigger_n.value;
            readback_data_var[31:1] = 31'h0;
        end
        if(rd_mux_addr == 32'hc) begin
            readback_data_var[31:0] = hwif_in.hwpe_ctrl.status.status0.next;
        end
        if(rd_mux_addr == 32'h10) begin
            readback_data_var[7:0] = hwif_in.hwpe_ctrl.running_job.running_job.next;
            readback_data_var[31:8] = 24'h0;
        end
        if(rd_mux_addr == 32'h14) begin
            readback_data_var[31:2] = 30'h0;
        end
        if(rd_mux_addr == 32'h18) begin
            readback_data_var[31:0] = 32'h0;
        end
        if(rd_mux_addr == 32'h1c) begin
            readback_data_var[31:0] = 32'h0;
        end
        if(rd_mux_addr == 32'h20) begin
            readback_data_var[31:0] = field_storage.hwpe_job_dep.row_ptr_addr.row_ptr_base_addr.value;
        end
        if(rd_mux_addr == 32'h24) begin
            readback_data_var[31:0] = field_storage.hwpe_job_dep.b_addr.b_base_addr.value;
        end
        if(rd_mux_addr == 32'h28) begin
            readback_data_var[31:0] = field_storage.hwpe_job_dep.a_addr.a_base_addr.value;
        end
        if(rd_mux_addr == 32'h2c) begin
            readback_data_var[31:0] = field_storage.hwpe_job_dep.col_id_addr.col_id_base_addr.value;
        end
        if(rd_mux_addr == 32'h30) begin
            readback_data_var[31:0] = field_storage.hwpe_job_dep.c_addr.c_base_addr.value;
        end
        if(rd_mux_addr == 32'h34) begin
            readback_data_var[15:0] = field_storage.hwpe_job_dep.lengths.row_ptr_num_words.value;
            readback_data_var[31:16] = field_storage.hwpe_job_dep.lengths.b_num_words.value;
        end
        if(rd_mux_addr == 32'h38) begin
            readback_data_var[31:0] = hwif_in.hwpe_job_dep.mopcnt.op_id_cnt.next;
        end
        if(rd_mux_addr == 32'h40) begin
            readback_data_var[31:0] = 32'h0;
        end
        readback_data = readback_data_var;
        readback_done = decoded_req & ~decoded_req_is_wr;
        readback_err = '0;
    end

    assign cpuif_rd_ack = readback_done;
    assign cpuif_rd_data = readback_data;
    assign cpuif_rd_err = readback_err;
endmodule
